    __shared__ float warp_sums[32];
    int lane = threadIdx.x % warpSize;
    int warp_id = threadIdx.x / warpSize;

    if (lane == 0) {
        warp_sums[warp_id] = sum;
    }
    __syncthreads();

    // Final reduction across all warps, with the first warp handling the remaining partial sums based on the total number of warps in the block

. Threads load their corresponding warp sum if they're within bounds, otherwise zero. The first warp then performs another shuffle-based reduction and writes the final result to the output matrix at the appropriate row position.

